 "content": "def transform(grid):
    """Extend the 2x2 zero marker's column wipe and preserve 2s on its rows."""
    out = [row[:] for row in grid]
    zero_cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 0]
    if not zero_cells:
        return out
    rows = sorted({r for r, _ in zero_cells})
    cols = sorted({c for _, c in zero_cells})
    # The marker is a rectangular zero block; wipe its columns and rows,
    # retaining color 2 on the marker's rows.
    for r in range(len(out)):
        for c in cols:
            out[r][c] = 0
    for r in rows:
        for c in range(len(out[r])):
            if out[r][c] != 2:
                out[r][c] = 0
    return out

